package in.kabadiwala.connect.controller; import in.kabadiwala.connect.dto.ApiResponse; import in.kabadiwala.connect.repository.TransactionRepository; import in.kabadiwala.connect.service.ReceiptService; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/transactions") public class TransactionController {private final TransactionRepository r;private final ReceiptService receipts;public TransactionController(TransactionRepository r,ReceiptService x){this.r=r;receipts=x;} @GetMapping ApiResponse<?> list(Authentication a){String u=a.getName();return ApiResponse.ok("Transactions",r.findAll().stream().filter(t->u.equals(t.collectorId)||u.equals(t.recyclerId)).toList());} @GetMapping("/{id}/receipt.pdf") ResponseEntity<byte[]> pdf(Authentication a,@PathVariable String id){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=kabadiwala-receipt-"+id+".pdf").contentType(MediaType.APPLICATION_PDF).body(receipts.pdf(a.getName(),id));}}
